from pathlib import Path
from html import escape
from urllib.parse import quote
import json

ROOT=Path(__file__).parent
OUT=ROOT/'dist'
books=json.loads((ROOT/'sources/books-original.json').read_text(encoding='utf-8'))
titles=['Venezuela bajo el sol','El ingenioso hidalgo de la Mancha','Una ronda del tiempo','Cuentos impertinentes','La tienda de los muertos','Huellas cifradas','Sonetos','Ileso albedrío','Reforma electoral']
genres=['Historia','Poesía','Narrativa','Narrativa','Narrativa','Poesía','Poesía','Poesía','Derecho']
summaries=[
 'Un recorrido por el poder político venezolano, desde la Colonia hasta el siglo XXI, apoyado en historiadores y experiencias diplomáticas.',
 'Sonetos dedicados al universo de Don Quijote y a la obra de Cervantes.',
 'La memoria de Pamplona, su paisaje y las transformaciones de su patrimonio urbano.',
 'Relatos nacidos de vivencias, recuerdos, sentimientos y personajes que reaparecen en la imaginación del autor.',
 'Una narración sobre la vida cotidiana de un pueblo y quienes buscan otro porvenir en la capital.',
 'Poemas de distintas épocas que reúnen las marcas íntimas del amor, la memoria y el tiempo.',
 'Sonetos de Augusto Ramírez Villamizar y de su hijo, unidos por la enseñanza y la práctica de la poesía.',
 'Primeros poemas del autor, escritos en su juventud y alentados por su padre y por el reconocimiento de Eduardo Cote Lamus.',
 'Reflexiones sobre reformas políticas, instituciones electorales y las expectativas que despiertan en la sociedad.'
]
